// 精确原业务source唯一字段序；间断服务逐段保存，绝不以floor后的整数跨度代替。
#pragma once
#include "life_work_period.hpp"
#include "work_period_codec_fields.hpp"
namespace hanmo::resident::life_work_fields {
using namespace exact_fields;
template<class C> Status ref(C& c,LifeWorkPeriodSourceRef& v){return work_fields::life_period_ref(c,v);}
template<class C> Status service_ref(C& c,LifeWorkServiceSourceRef& v){c.object("source_ref",[&](auto& x){return source(x,v.source_ref);});return schema(c,"source_schema",v.source_schema);}
template<class C> Status segment(C& c,LifeWorkServiceSegment& v){c.object("actual_span",[&](auto& x){x.object("from",[&](auto& z){return moment(z,v.actual_span.from);});return x.object("to",[&](auto& z){return moment(z,v.actual_span.to);});});c.object("provided_service_units",[&](auto& x){return work_units(x,v.provided_service_units);});c.sequence("actual_service_source_refs",v.actual_service_source_refs,[](auto& x,auto& value){return service_ref(x,value);});if(c.status().ok&&(v.actual_span.from.half_day_tick<0||take(compare_world_moments(v.actual_span.from,v.actual_span.to))>=0||v.actual_service_source_refs.empty()))return c.reject("InvalidLifeWorkServiceSegment");return c.status();}
template<class C> Status profile(C& c,LifeHalfDayStageGateProfile& v){StableId name;if(!c.reading()){const auto* actual=life_half_day_stage_profile_name(v);if(!actual)return c.reject("UnknownLifeHalfDayGateProfile");name=actual;}required_ref(c,"gate_profile",name);if(c.status().ok&&c.reading()){bool found=false;for(unsigned i=0;i<7;++i)if(name==life_half_day_stage_profile_name(static_cast<LifeHalfDayStageGateProfile>(i))){v=static_cast<LifeHalfDayStageGateProfile>(i);found=true;break;}if(!found)return c.reject("UnknownLifeHalfDayGateProfile");}return c.status();}
template<class C> Status body(C& c,LifeWorkPeriodView& v){c.object("ref",[&](auto& x){return ref(x,v.ref);});c.object("execution_binding",[&](auto& x){return work_fields::binding(x,v.execution_binding);});profile(c,v.gate_profile);c.object("stage_rule_source_ref",[&](auto& x){return source(x,v.stage_rule_source_ref);});c.field("completed_halfday_ordinal",v.completed_halfday_ordinal);c.object("applied_at",[&](auto& x){return moment(x,v.applied_at);});c.sequence("service_segments",v.service_segments,[](auto& x,auto& value){return segment(x,value);});c.object("consumed_service_units",[&](auto& x){return work_units(x,v.consumed_service_units);});c.sequence("actual_actor_roles",v.actual_actor_roles,[](auto& x,auto& role){required_ref(x,"actor_id",role.actor_id);return required_ref(x,"role",role.role);});references(c,"actual_labor_allocations",v.actual_labor_allocations);references(c,"facility_claim_refs",v.facility_claim_refs);work_fields::source_list(c,"resource_effect_refs",v.resource_effect_refs);work_fields::source_list(c,"exertion_source_refs",v.exertion_source_refs);work_fields::source_list(c,"original_stage_result_refs",v.original_stage_result_refs);c.sequence("completed_stage_ordinals",v.completed_stage_ordinals,[](auto& x,auto& value){return x.field("value",value);});if(c.status().ok&&(v.completed_halfday_ordinal<0||v.applied_at.half_day_tick<0||v.service_segments.empty()||!std::holds_alternative<ActorActionWorkBinding>(v.execution_binding)))return c.reject("InvalidLifeWorkPeriodSource");return c.status();}
}
